INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(959279, '2', '1', '0', '0', '0', '0', '0', '0', '$N, by my eternal soul, it is good to see you!  I don\'t know why the Exodar crashed.  Only those of us that were in this part of the ship remain.$B$BThere\'s not much time if we\'re to save everyone that we can!', '12340'),
(959280, '1', '0', '0', '0', '0', '0', '0', '0', 'Regrettable that those creatures had to die so that we might live - indiscriminate killing is not the draenei way.  However, the blood you gathered will replenish our healing crystals, so their deaths will not be in vain.', '12340'),
(959283, '4', '0', '0', '0', '0', '0', '0', '0', 'The Light be praised! You\'ve done what only a true $g hero : heroine; could have done, $N! The draenei you saved owes their continued life to your selflessness!$B$BPlease, take this supply pouch. You look like you can use it more than I.', '12340'),
(959463, '5', '0', '0', '0', '0', '0', '0', '0', 'Let us hope that this ointment will strengthen her spirit!', '12340'),
(959473, '1', '0', '0', '0', '0', '0', '0', '0', 'Watch as the plant works its magic.', '12340'),
(959505, '0', '0', '0', '0', '0', '0', '0', '0', 'You say that you\'ve found one of our crew and that she is injured? I will send one of my crewmen to your village immediately!', '12340'),
(959603, '0', '0', '0', '0', '0', '0', '0', '0', 'So you need to go to the Exodar?$B$BThat\'s going to be a long trip, but don\'t worry, I have a way to get you there very quickly.', '12340'),
(959604, '0', '0', '0', '0', '0', '0', '0', '0', 'So you\'ve brought Topher\'s list. Excellent! I was hoping to receive this today. Let\'s see what he needs.$B$B<Nurguni reads over the list and begins placing various items in a box.>$B$BThat\'s most of what he requested. The pieces for the beds are simply too large to be delivered by hippogryph, but I\'ll make arrangements to have them sent by wagon. ', '12340'),
(959605, '0', '0', '0', '0', '0', '0', '0', '0', 'So you\'re headed back to Blood Watch with this package? No problem at all, $c. Just speak with me again and we\'ll get you on your way with those supplies.', '12340'),
(959606, '0', '0', '0', '0', '0', '0', '0', '0', '<Handing Topher the box, you tell him that Nurguni is making arrangements to have the larger items delivered by wagon.>$B$BSplendid! Now, I\'ll finally be able to set up some beds and a first aid station so that we can better treat the wounded and any survivors we encounter.$B$BI can\'t thank you enough for your help, $N. You have my thanks and that of the Blood Watch\'s vindicators.', '12340'),
(959612, '0', '0', '0', '0', '0', '0', '0', '0', 'Well done, $N. Well done indeed! You are turning out to be a special $R - a cut above the others of your age. Take this as a reward!', '12340'),
(959753, '0', '0', '0', '0', '0', '0', '0', '0', 'I am in need of your services, $N. I have a plan to topple the entire Sunhawk army, but before we can progress, we need to gather some vital information.$B$BWe need to identify the weaknesses in their primary defense. Unfortunately, we have been unable to get close enough to the Vector Coil to gauge their defenses. If we could get the prisoner to talk, we could get the information that we needed to break through the line and destroy the Vector Coil.$B$BYou heard me, I want to blow the damned thing up.', '12340'),
(959756, '0', '0', '0', '0', '0', '0', '0', '0', 'A-ha! Well done, $N. Well done, indeed. Are you ready to eradicate the blood elf menace from our island forever?', '12340'),
(959759, '0', '0', '0', '0', '0', '0', '0', '0', 'You have saved the whole of Bloodmyst and Azuremyst, securing the $R way of life on Azeroth, $N! For this, there can be no amount of thanks, no reward, nothing large enough in scope to truly express our appreciation.$B$BYet, there are still so many that were left behind on Draenor who cannot be here for this historic event. You must find your way back. Find your way back to the Outland, Hero of Argus. Bring our people home. Home to the land that you saved. Home to Azeroth...', '12340'),
(959760, '0', '0', '0', '0', '0', '0', '0', '0', 'Perhaps you will be the one to deliver our people into a new age of prosperity and peace.', '12340'),
(959761, '0', '0', '0', '0', '0', '0', '0', '0', 'Hopefully a hero arrives before they are able to call forth reinforcements to guard the area you just secured.', '12340'),
(959762, '0', '0', '0', '0', '0', '0', '0', '0', 'These islands will serve as the home to thousands. Most of these people will remain here their entire lives. If you so desired, you could do the same. But that\'s not what you want, is it, $N?$B$B<Velen nods.>$B$BYou will do many more great things before you pass. You must embrace your destiny and meet it head on!$B$BBefore you leave, I present you with two gifts: This tabard is worn by only the most revered of the Hand of Argus and this signet ring worn by our wisest sages. Wear them both with pride, $N.', '12340');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(959279, '1', '0', '', '12340'),
(959280, '6', '6', '$N, have you harvested the necessary moth blood for the healing crystals yet?  With survivors scattered all over the vale, time is of the essence!', '12340'),
(959283, '1', '0', 'We\'ll survive this yet with your help.', '12340'),
(959463, '1', '1', 'I fear that her health is in steady decline.', '12340'),
(959473, '1', '1', 'Do not waste time, $g boy:girl;.', '12340'),
(959505, '1', '0', NULL, '12340'),
(959603, '1', '0', 'Good day, $N. Are you interested in renting a hippogryph?', '12340'),
(959604, '1', '0', 'Greetings, friend. You look like you\'ve come a long way. How can I help you?', '12340'),
(959605, '1', '0', 'Where are you headed, $C?', '12340'),
(959606, '1', '0', 'Welcome back, $N. Was Nurguni able to gather everything on the list? ', '12340'),
(959612, '1', '0', NULL, '12340'),
(959753, '1', '0', NULL, '12340'),
(959756, '1', '0', NULL, '12340'),
(959759, '1', '0', NULL, '12340'),
(959760, '1', '0', NULL, '12340'),
(959761, '1', '0', 'Do you see any unusually brave and powerful draenei around here?', '12340'),
(959762, '1', '0', NULL, '12340');
