INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(950363, '1', '0', '0', '0', '0', '0', '0', '0', 'Another of the walking dead, hm? Must have been quite a shock, waking up in the crypt with only the cold and Mordo to greet you...$b$bI see the confusion on your face. Let me try to explain our... situation... to you.$b$bWe have been freed from the control of the Lich King by our new leader, Lady Sylvanas. The Dark Lady guides us in our war against the hated Scourge and the holdouts of humanity who dog our every step.', '12340'),
(955847, '0', '0', '0', '0', '0', '0', '0', '0', 'You are indeed a special hero, $N. We welcome you to the world of Azeroth, and offer you one of these unique gifts!', '12340'),
(956321, '1', '0', '0', '0', '0', '0', '0', '0', 'Ah, an order for supplies.  You will want to take this to the Undercity, no doubt.  And quickly, for the Sepulcher must not be left under stocked.', '12340'),
(956322, '6', '0', '0', '0', '0', '0', '0', '0', 'This crate must reach the Sepulcher in Silverpine? That is easily done; our bats fly there daily.', '12340'),
(956323, '1', '0', '0', '0', '0', '0', '0', '0', 'An order from the Sepulcher? Very well. It is an honor to serve those who serve our Dark Lady.', '12340'),
(956324, '1', '0', '0', '0', '0', '0', '0', '0', 'Good work, $N. These weapons will ensure our Deathguards don\'t get caught unprepared.$B$BYou have done a valuable service for our Dark Lady.', '12340');
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(950363, '1', '0', NULL, '12340'),
(955847, '1', '0', 'Greetings! It is a pleasure to meet you!$B$BI see you have a special voucher. Give it to me and I will offer you something in exchange.', '12340'),
(956321, '6', '0', 'You appear to be on official business...', '12340'),
(956322, '1', '0', 'If you must travel a long distance, then a bat is your best option.', '12340'),
(956323, '6', '0', 'I keep my weapons in top condition. They are cleaned and ready for use.', '12340'),
(956324, '6', '0', '$N, you return. Do you have our supplies from the Undercity?', '12340');
